const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const V = input[idx++];
const N = input[idx++];
const M = input[idx++];
const width = V + 1;

const graph = Array.from({ length: N }, () => []);

for (let i = 0; i < M; i++) {
  const a = input[idx++] - 1;
  const b = input[idx++] - 1;
  const time = input[idx++];
  const cost = input[idx++];

  graph[a].push([b, time, cost]);
  graph[b].push([a, time, cost]);
}

const start = input[idx++] - 1;
const destination = input[idx++] - 1;

const stateCount = N * width;
const dist = new Float64Array(stateCount);
dist.fill(Infinity);

const position = new Int32Array(stateCount);
position.fill(-1);

const heap = new Int32Array(stateCount);
let heapSize = 0;

function siftUp(i) {
  const state = heap[i];
  while (i > 0) {
    const parent = (i - 1) >> 1;
    const parentState = heap[parent];
    if (dist[parentState] <= dist[state]) break;
    heap[i] = parentState;
    position[parentState] = i;
    i = parent;
  }
  heap[i] = state;
  position[state] = i;
}

function siftDown(i) {
  const state = heap[i];
  while (true) {
    let child = i * 2 + 1;
    if (child >= heapSize) break;
    if (child + 1 < heapSize && dist[heap[child + 1]] < dist[heap[child]]) {
      child++;
    }
    if (dist[state] <= dist[heap[child]]) break;
    heap[i] = heap[child];
    position[heap[i]] = i;
    i = child;
  }
  heap[i] = state;
  position[state] = i;
}

function insertOrDecrease(state) {
  if (position[state] === -1) {
    heap[heapSize] = state;
    position[state] = heapSize;
    siftUp(heapSize);
    heapSize++;
  } else {
    siftUp(position[state]);
  }
}

function popMin() {
  const minState = heap[0];
  position[minState] = -2;
  heapSize--;

  if (heapSize > 0) {
    const last = heap[heapSize];
    heap[0] = last;
    position[last] = 0;
    siftDown(0);
  }

  return minState;
}

const initialState = start * width;
dist[initialState] = 0;
insertOrDecrease(initialState);

let answer = -1;

while (heapSize > 0) {
  const state = popMin();
  const time = dist[state];
  const island = Math.floor(state / width);
  const spent = state % width;

  if (island === destination) {
    answer = time;
    break;
  }

  for (const [nextIsland, travelTime, cost] of graph[island]) {
    const nextSpent = spent + cost;
    if (nextSpent > V) continue;

    const nextState = nextIsland * width + nextSpent;
    const nextTime = time + travelTime;

    if (nextTime < dist[nextState] && position[nextState] !== -2) {
      dist[nextState] = nextTime;
      insertOrDecrease(nextState);
    }
  }
}

console.log(answer);
